{"script":"() => {
  const results = {};
  // Find all prices
  document.querySelectorAll('[id^="_r_"]').forEach(input => {
    const label = document.querySelector(`label[for="${input.id}"]`);
    const text = (label ? label.innerText : '') + ' ' + input.outerHTML.substring(0, 200);
    if (text.includes('$') || text.includes('MacBook') || text.includes('chip') || text.includes('GPU') || text.includes('CPU')) {
      results[input.id] = { value: input.value, text: text.trim().substring(0, 300) };
    }
  });
  // Also get the prices from page
  results.bodyText = document.body.innerText.substring(0, 3000);
  return results;
}"}

